import { readdir, writeFile } from 'node:fs/promises';

const files = (await readdir('src/icons')).filter((f) => f.endsWith('.svg')).sort();
const names = files.map((f) => f.replace(/\.svg$/, ''));

// Typed consts keep emitted .d.ts free of `.svg` module references.
const source = [
  '// Generated by scripts/generate-icons.mjs. Do not edit.',
  "import type { FC, SVGProps } from 'react';",
  '',
  ...names.map((n) => `import ${n}Svg from './${n}.svg';`),
  '',
  'export type IconComponent = FC<SVGProps<SVGSVGElement>>;',
  '',
  ...names.map((n) => `export const ${n}: IconComponent = ${n}Svg;`),
  '',
].join('\n');

await writeFile('src/icons/index.ts', source);
console.log(`Generated ${names.length} icon exports`);
